// ── quiz + flashcard pop-up (needs escapeHtml, haptic and showAlert from the host page) ──
    // ─── STUDY TOOLS: quiz + flashcard pop-up (the AI creates these via tool calls) ─────────
    let study = null; // { data, ...state } while the overlay is open

    function studyEl(tag, cls, text) {
        const e = document.createElement(tag);
        if (cls) e.className = cls;
        if (text !== undefined) e.textContent = text;
        return e;
    }
    function studyChipHTML(data) {
        const isQuiz = data.type === 'quiz';
        const n = isQuiz ? `${data.questions.length} question${data.questions.length === 1 ? '' : 's'}` : `${data.cards.length} card${data.cards.length === 1 ? '' : 's'}`;
        return `<button type="button" class="study-chip" data-study="${encodeURIComponent(JSON.stringify(data))}">`
            + `<svg class="icon"><use href="#${isQuiz ? 'icon-info' : 'icon-tag'}"/></svg>`
            + `<span class="study-chip-text"><b>${escapeHtml(data.title)}</b><small>${isQuiz ? 'Quiz' : 'Flashcards'} · ${n} · tap to open</small></span></button>`;
    }
    // reopen from a saved chip anywhere in the chat
    document.getElementById('chat-box').addEventListener('click', (e) => {
        const chip = e.target.closest?.('.study-chip');
        if (!chip) return;
        try { openStudy(JSON.parse(decodeURIComponent(chip.dataset.study))); } catch (err) { showAlert("Couldn't open that one.", 'Study'); }
    });

    function studyValid(d) {
        if (d?.type === 'quiz') return Array.isArray(d.questions) && d.questions.every(q => q && Array.isArray(q.options) && Number.isInteger(q.answer));
        if (d?.type === 'flashcards') return Array.isArray(d.cards) && d.cards.every(c => c && c.front && c.back);
        return false;
    }

    function openStudy(data) {
        if (!studyValid(data)) return;
        const isQuiz = data.type === 'quiz';
        study = isQuiz
            ? { data, i: 0, score: 0, streak: 0, best: 0, missed: [], locked: false }
            : { data, queue: shuffleArr(data.cards.map((_, i) => i)), known: 0, reviews: 0, flipped: false };
        document.getElementById('studyKind').textContent = isQuiz ? 'Quiz' : 'Flashcards';
        document.getElementById('studyTitle').textContent = data.title;
        document.getElementById('studyBody').classList.remove('study-result');
        document.getElementById('studyOverlay').classList.add('open');
        haptic('success');
        isQuiz ? renderQuizQ() : renderCard();
    }

    function closeStudy() {
        document.getElementById('studyOverlay')?.classList.remove('open');
        const sb = document.getElementById('studyBody');
        sb.innerHTML = ''; sb.classList.remove('study-result');
        document.querySelector('.confetti')?.remove();
        study = null;
    }
    function shuffleArr(a) { for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a; }
    function setStudyProgress(frac) { document.getElementById('studyBar').style.width = `${Math.round(Math.max(0, Math.min(1, frac)) * 100)}%`; }

    // ── quiz ──
    function renderQuizQ() {
        const q = study.data.questions[study.i], total = study.data.questions.length;
        const body = document.getElementById('studyBody');
        body.innerHTML = '';
        study.locked = false;
        setStudyProgress(study.i / total);

        const meta = studyEl('div', 'study-meta');
        meta.append(studyEl('span', '', `Question ${study.i + 1} of ${total}`));
        const right = studyEl('span'); right.innerHTML = study.streak >= 2 ? `<b>🔥 ${study.streak} in a row</b>` : `Score ${study.score}`;
        meta.append(right);
        body.append(meta, studyEl('h2', 'q-text', q.question));

        const opts = studyEl('div', 'q-opts');
        opts.setAttribute('role', 'group'); opts.setAttribute('aria-label', 'Answer choices');
        q.options.forEach((text, idx) => {
            const b = studyEl('button', 'q-opt'); b.type = 'button'; b.dataset.idx = idx;
            b.append(studyEl('span', 'q-letter', String.fromCharCode(65 + idx)), studyEl('span', '', text));
            b.addEventListener('click', () => chooseOption(idx));
            opts.append(b);
        });
        body.append(opts);
        setTimeout(() => opts.querySelector('.q-opt')?.focus({ preventScroll: true }), 60);
    }

    function chooseOption(idx) {
        if (!study || study.locked || study.data.type !== 'quiz') return;
        study.locked = true;
        const q = study.data.questions[study.i], total = study.data.questions.length;
        const correct = idx === q.answer;
        if (correct) { study.score++; study.streak++; study.best = Math.max(study.best, study.streak); haptic('success'); }
        else { study.streak = 0; study.missed.push({ q, chosen: idx }); haptic('error'); }

        document.querySelectorAll('#studyBody .q-opt').forEach((b, i) => {
            b.disabled = true;
            if (i === q.answer) b.classList.add('correct');
            else if (i === idx) b.classList.add('wrong');
            else b.classList.add('dim');
        });
        setStudyProgress((study.i + 1) / total);

        const body = document.getElementById('studyBody');
        const fb = studyEl('div', `q-feedback ${correct ? 'good' : 'bad'}`);
        fb.append(studyEl('b', '', correct ? '✓ Correct!' : `✗ Not quite — it's ${String.fromCharCode(65 + q.answer)}`));
        if (q.explanation) fb.append(document.createTextNode(q.explanation));
        const actions = studyEl('div', 'study-actions');
        const next = studyEl('button', 'btn-ui', study.i + 1 < total ? 'Next question →' : 'See results'); next.type = 'button';
        next.addEventListener('click', nextQuestion);
        actions.append(next);
        body.append(fb, actions);
        next.focus({ preventScroll: true });
        next.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
    }

    function nextQuestion() {
        if (!study) return;
        haptic('tap');
        study.i++;
        study.i < study.data.questions.length ? renderQuizQ() : renderQuizResult();
    }

    function renderQuizResult() {
        const total = study.data.questions.length, pct = study.score / total;
        const body = document.getElementById('studyBody');
        body.innerHTML = '';
        body.classList.add('study-result');
        setStudyProgress(1);
        const [head, sub] = pct === 1 ? ['Perfect score! 🎉', 'You nailed every question.']
            : pct >= 0.8 ? ['Excellent work!', 'You really know this.']
            : pct >= 0.6 ? ['Nice job!', 'A little more practice and you\'ve got it.']
            : pct >= 0.4 ? ['Getting there', 'Review the misses below and try again.']
            : ['Keep practicing', 'Every miss is a chance to learn — try again.'];
        const ring = studyEl('div', 'score-ring');
        ring.innerHTML = `<svg viewBox="0 0 120 120" aria-hidden="true"><circle class="track" cx="60" cy="60" r="54"/><circle class="fill" cx="60" cy="60" r="54"/></svg>`
            + `<div class="num">${study.score}/${total}<small>${Math.round(pct * 100)}%</small></div>`;
        body.append(ring, studyEl('div', 'result-head', head), studyEl('div', 'result-sub', study.best >= 3 ? `${sub} Best streak: ${study.best} 🔥` : sub));
        requestAnimationFrame(() => requestAnimationFrame(() => { ring.querySelector('.fill').style.strokeDashoffset = String(339.3 * (1 - pct)); }));

        const actions = studyEl('div', 'study-actions');
        actions.style.width = '100%';
        const retry = studyEl('button', 'btn-ui', 'Retry quiz'); retry.type = 'button';
        retry.addEventListener('click', () => { body.classList.remove('study-result'); openStudy(study.data); });
        const done = studyEl('button', 'btn-ui', 'Done'); done.type = 'button'; done.addEventListener('click', closeStudy);
        actions.append(retry, done);
        if (study.missed.length) {
            const review = studyEl('button', 'btn-ui', `Review ${study.missed.length} missed`); review.type = 'button';
            review.addEventListener('click', () => { review.remove(); body.insertBefore(missedList(), actions); });
            actions.prepend(review);
        }
        body.append(actions);
        haptic(pct >= 0.6 ? 'success' : 'nav');
        if (pct === 1) confettiBurst();
        retry.focus({ preventScroll: true });
    }

    function missedList() {
        const wrap = studyEl('div', 'missed');
        study.missed.forEach(({ q, chosen }) => {
            const it = studyEl('div', 'missed-item');
            it.append(studyEl('b', '', q.question));
            const a = studyEl('div'); a.innerHTML = 'Answer: <span class="ans"></span>';
            a.querySelector('.ans').textContent = q.options[q.answer];
            it.append(a);
            if (chosen !== q.answer) it.append(studyEl('div', '', `You picked: ${q.options[chosen]}`));
            if (q.explanation) it.append(studyEl('div', '', q.explanation));
            wrap.append(it);
        });
        return wrap;
    }

    function confettiBurst() {
        if (window.matchMedia?.('(prefers-reduced-motion: reduce)').matches) return;
        const layer = studyEl('div', 'confetti');
        const colors = ['#22e5ff', '#2f6bff', '#19c37d', '#ffd23f', '#ff4d6d', '#eaf6ff'];
        for (let i = 0; i < 44; i++) {
            const c = document.createElement('i');
            c.style.left = Math.random() * 100 + '%';
            c.style.background = colors[i % colors.length];
            c.style.animationDuration = (1.6 + Math.random() * 1.6) + 's';
            c.style.animationDelay = (Math.random() * 0.5) + 's';
            layer.append(c);
        }
        document.body.append(layer);
        setTimeout(() => layer.remove(), 4000);
    }

    // ── flashcards ──
    function renderCard() {
        const body = document.getElementById('studyBody');
        const total = study.data.cards.length;
        body.innerHTML = '';
        if (!study.queue.length) { renderDeckDone(); return; }
        study.flipped = false;
        setStudyProgress(study.known / total);
        const card = study.data.cards[study.queue[0]];

        const meta = studyEl('div', 'study-meta');
        meta.append(studyEl('span', '', `${study.known} of ${total} learned`), studyEl('span', '', `${study.queue.length} left`));
        const fc = studyEl('button', 'fc'); fc.type = 'button';
        fc.setAttribute('aria-label', 'Flashcard — press to flip');
        const inner = studyEl('div', 'fc-inner');
        const front = studyEl('div', 'fc-face fc-front'); front.append(studyEl('span', 'fc-tag', 'Term'), studyEl('span', '', card.front));
        const back = studyEl('div', 'fc-face fc-back'); back.append(studyEl('span', 'fc-tag', 'Answer'), studyEl('span', '', card.back));
        inner.append(front, back); fc.append(inner);
        fc.addEventListener('click', flipCard);

        const actions = studyEl('div', 'study-actions');
        const again = studyEl('button', 'btn-ui btn-again', '↺ Again'); again.type = 'button';
        const got = studyEl('button', 'btn-ui btn-got', 'Got it ✓'); got.type = 'button';
        again.addEventListener('click', () => rateCard(false));
        got.addEventListener('click', () => rateCard(true));
        actions.append(again, got);
        body.append(meta, fc, studyEl('div', 'fc-hint', 'Tap the card (or press Space) to flip · ← Again · → Got it'), actions);
        setTimeout(() => fc.focus({ preventScroll: true }), 60);
    }
    function flipCard() {
        if (!study || study.data.type !== 'flashcards') return;
        study.flipped = !study.flipped;
        document.querySelector('#studyBody .fc')?.classList.toggle('flipped', study.flipped);
        haptic('select');
    }
    function rateCard(knewIt) {
        if (!study || !study.queue.length) return;
        study.reviews++;
        const idx = study.queue.shift();
        if (knewIt) { study.known++; haptic('success'); }
        else { study.queue.push(idx); haptic('nav'); }
        renderCard();
    }
    function renderDeckDone() {
        const total = study.data.cards.length;
        const body = document.getElementById('studyBody');
        body.classList.add('study-result');
        setStudyProgress(1);
        body.innerHTML = '';
        body.append(studyEl('div', 'result-head', 'Deck complete! 🎉'),
            studyEl('div', 'result-sub', `You learned all ${total} cards in ${study.reviews} review${study.reviews === 1 ? '' : 's'}.`));
        const actions = studyEl('div', 'study-actions'); actions.style.width = '100%';
        const again = studyEl('button', 'btn-ui', 'Study again'); again.type = 'button';
        again.addEventListener('click', () => { body.classList.remove('study-result'); openStudy(study.data); });
        const done = studyEl('button', 'btn-ui', 'Done'); done.type = 'button'; done.addEventListener('click', closeStudy);
        actions.append(again, done);
        body.append(actions);
        haptic('success'); confettiBurst();
        again.focus({ preventScroll: true });
    }

    // number keys pick answers, arrows drive flashcards (Enter/Space use the focused button as normal)
    document.addEventListener('keydown', (e) => {
        if (!study || !document.getElementById('studyOverlay').classList.contains('open')) return;
        if (study.data.type === 'quiz') {
            const n = parseInt(e.key, 10);
            if (n >= 1 && n <= study.data.questions[study.i]?.options.length && !study.locked) { e.preventDefault(); chooseOption(n - 1); }
            else if (e.key === 'ArrowRight' && study.locked) { e.preventDefault(); nextQuestion(); }
        } else if (study.queue?.length) {
            if (e.key === 'ArrowLeft') { e.preventDefault(); rateCard(false); }
            else if (e.key === 'ArrowRight') { e.preventDefault(); rateCard(true); }
        }
    });

